:root{
  --bg:#0f1220;
  --card:#171a2b;
  --ink:#eef0ff;
  --muted:#b9bddb;
  --line:#2a2f4a;
  --accent:#8be9fd;
  --good:#7CFFB2;
  --bad:#ff7a90;
  --warn:#ffd37a;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 600px at 20% 0%, #1b2150 0%, var(--bg) 55%);color:var(--ink);font:16px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:22px}
.hdr{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:14px}
h1{font-size:26px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.card{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));border:1px solid var(--line);border-radius:14px;padding:16px 16px 14px;margin:14px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
h2{font-size:18px;margin:0 0 8px 0}
.inst{margin:0 0 12px 0;color:var(--muted)}
.ex{cursor:pointer;color:var(--accent);border-bottom:1px dashed rgba(139,233,253,.5)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:10px 0 12px}
.lab{min-width:56px;color:var(--muted)}
.in{flex:1;min-width:260px;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink);outline:none}
.in:focus{border-color:rgba(139,233,253,.7);box-shadow:0 0 0 3px rgba(139,233,253,.12)}
.btn{padding:10px 12px;border-radius:10px;border:1px solid rgba(139,233,253,.35);background:rgba(139,233,253,.12);color:var(--ink);cursor:pointer}
.btn:hover{background:rgba(139,233,253,.18)}
.btn.ghost{border-color:var(--line);background:transparent;color:var(--muted)}
.btn.ghost:hover{background:rgba(255,255,255,.04);color:var(--ink)}
.grid{display:grid;grid-template-columns:1fr 1.2fr;gap:12px}
@media (max-width:860px){.grid{grid-template-columns:1fr}}
.pane{border:1px solid var(--line);border-radius:12px;padding:12px;background:rgba(0,0,0,.18)}
.pane h3{margin:0 0 8px 0;font-size:14px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.hint{margin-top:8px;color:var(--muted);font-size:13px}
.rules{display:flex;flex-direction:column;gap:8px}
.rules label{display:flex;gap:8px;align-items:flex-start;color:var(--ink)}
