.small{font-size:13px;color:var(--muted)}
.out{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
.outrow{display:grid;grid-template-columns:1fr 1fr;gap:12px}
@media (max-width:700px){.outrow{grid-template-columns:1fr}}
.k{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px}
.big{font-size:22px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c0f1c;min-height:48px;display:flex;align-items:center}
.notes{margin-top:10px}
.notes summary{cursor:pointer;color:var(--accent)}
