// Herodian -ων accent toy (offline, vanilla JS)
(() => {
  const $ = (sel, el=document) => el.querySelector(sel);
  const $$ = (sel, el=document) => Array.from(el.querySelectorAll(sel));

  // Combining marks
  const ACUTE = "\u0301";
  const GRAVE = "\u0300";
  const CIRC  = "\u0342"; // perispomeni

  // Basic Greek vowel set (incl. common diacritics as precomposed)
  const VOWELS = new Set([
    ..."αεηιουωΑΕΗΙΟΥΩ",
    ..."άέήίόύώΆΈΉΊΌΎΏ",
    ..."ὰὲὴὶὸὺὼᾺῈῊῚῸῪῺ",
    ..."ᾶῆῖῦῶᾷῇῷᾆᾇᾦᾇᾆᾦ",
    ..."ἀἁἂἃἄἅἆἇἈἉἊἋἌἍἎἏ",
    ..."ἐἑἒἓἔἕἘἙἚἛἜἝ",
    ..."ἠἡἢἣἤἥἦἧἨἩἪἫἬἭἮἯ",
    ..."ἰἱἲἳἴἵἶἷἸἹἺἻἼἽἾἿ",
    ..."ὀὁὂὃὄὅὈὉὊὋὌὍ",
    ..."ὐὑὒὓὔὕὖὗὙὛὝὟ",
    ..."ὠὡὢὣὤὥὦὧὨὩὪὫὬὭὮὯ",
    ..."ϊϋΐΰῒῢῗῧΪΫ"
  ]);

  function stripPunct(s){
    return s.replace(/[\s\u00A0]+/g,' ').trim().replace(/[··.,;:!?()\[\]{}<>«»“”"'’]/g,'');
  }

  function nfd(s){ return s.normalize('NFD'); }
  function nfc(s){ return s.normalize('NFC'); }

  function removeCombiningAccents(s){
    // remove acute/grave/circumflex combining marks
    return nfd(s).replace(/[\u0300\u0301\u0342]/g,'');
  }

  function lastVowelIndex(nfdStr){
    // index in code units of last vowel base char (not combining)
    for(let i=nfdStr.length-1;i>=0;i--){
      const ch = nfdStr[i];
      if(ch >= '\u0300' && ch <= '\u036F') continue; // combining
      if(VOWELS.has(ch)) return i;
    }
    return -1;
  }

  function penultVowelIndex(nfdStr){
    let found = 0;
    for(let i=nfdStr.length-1;i>=0;i--){
      const ch = nfdStr[i];
      if(ch >= '\u0300' && ch <= '\u036F') continue;
      if(VOWELS.has(ch)){
        found++;
        if(found===2) return i;
      }
    }
    return -1;
  }

  function applyAccentAtVowel(word, which, mark){
    // which: 'last' or 'penult'
    let s = removeCombiningAccents(word);
    let d = nfd(s);
    const idx = which==='penult' ? penultVowelIndex(d) : lastVowelIndex(d);
    if(idx<0) return word;
    // insert combining mark right after vowel base char
    d = d.slice(0, idx+1) + mark + d.slice(idx+1);
    return nfc(d);
  }

  function detectEnding(clean){
    const d = removeCombiningAccents(clean).toLowerCase();
    if(d.endsWith('ιων')) return '-ιων';
    if(d.endsWith('ων')) return '-ων';
    return '—';
  }

  function toGraveOnLastAcute(word){
    // swap the last acute combining mark for grave (very simplified)
    let d = nfd(word);
    const pos = d.lastIndexOf(ACUTE);
    if(pos === -1) return word;
    d = d.slice(0,pos) + GRAVE + d.slice(pos+1);
    return nfc(d);
  }

  function accentByRule(input, rule){
    const raw = input.trim();
    if(!raw) return {out:'—', grave:'—', ending:'—'};

    // If phrase, accent only the last token (toy)
    const parts = raw.split(/\s+/);
    const last = parts[parts.length-1];
    const cleanLast = stripPunct(last);
    const ending = detectEnding(cleanLast);

    let accentedLast = cleanLast;

    if(rule==='oxytone'){
      accentedLast = applyAccentAtVowel(cleanLast, 'last', ACUTE);
    } else if(rule==='compound-bary'){
      // toy: put accent on penult (barytone-ish)
      accentedLast = applyAccentAtVowel(cleanLast, 'penult', ACUTE);
    } else if(rule==='compound-oxy'){
      accentedLast = applyAccentAtVowel(cleanLast, 'last', ACUTE);
    } else if(rule==='pro-local'){
      // if starts with προ, keep last acute; else just oxytone
      const base = removeCombiningAccents(cleanLast).toLowerCase();
      accentedLast = applyAccentAtVowel(cleanLast, 'last', ACUTE);
      if(!base.startsWith('προ')){
        // still show last acute, but warn via ending field later
      }
    } else if(rule==='ion-proper'){
      // toy: if ends -ιων, shift accent to penult; else last
      if(ending==='-ιων') accentedLast = applyAccentAtVowel(cleanLast, 'penult', ACUTE);
      else accentedLast = applyAccentAtVowel(cleanLast, 'last', ACUTE);
    }

    // Rebuild phrase
    const rebuilt = parts.slice(0,-1).concat([accentedLast]).join(' ');
    const grave = toGraveOnLastAcute(rebuilt);

    return {out:rebuilt, grave, ending};
  }

  const input = $('#in');
  const out = $('#out');
  const grave = $('#grave');
  const ending = $('#ending');

  function currentRule(){
    const r = $('input[name="rule"]:checked');
    return r ? r.value : 'oxytone';
  }

  function render(){
    const res = accentByRule(input.value, currentRule());
    out.textContent = res.out;
    grave.textContent = res.grave;
    ending.textContent = res.ending;
  }

  $('#go').addEventListener('click', render);
  input.addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
  $$('input[name="rule"]').forEach(r => r.addEventListener('change', render));
  $('#clear').addEventListener('click', ()=>{ input.value=''; render(); input.focus(); });

  $$('.ex').forEach(span => {
    span.addEventListener('click', ()=>{
      input.value = span.getAttribute('data-fill');
      render();
      input.focus();
    });
  });

  // Quiz
  const qmsg = $('#qmsg');
  function accentForQuiz(s){
    // default: oxytone -ων/-ιων
    return applyAccentAtVowel(s, 'last', ACUTE);
  }
  $$('.qbtn').forEach(btn => {
    btn.textContent = accentForQuiz(btn.textContent);
    btn.addEventListener('click', ()=>{
      const ok = btn.getAttribute('data-answer') === '1';
      qmsg.textContent = ok
        ? 'Nice: this one fits the “acute on -ών” pattern (toy-wise).'
        : 'Not this time: this one is presented as non-oxytone / compound-like in the passage (toy-wise).';
      qmsg.style.color = ok ? 'var(--good)' : 'var(--bad)';
    });
  });

  // Initial render
  render();
})();

